@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_pet_with_form(api_client, config_test_data, scenario_case):
    """
    Test the updatePetWithForm endpoint with various scenarios.
    """
    pet_id = scenario_case.get("petId", config_test_data.get("petId"))
    name = scenario_case.get("name")
    status = scenario_case.get("status")
    expected_status_code = scenario_case["statusCode"]

    # Request data
    params = {}
    if name:
        params['name'] = name
    if status:
        params['status'] = status

    # Validate request schema
