    request_data = {k: v for k, v in request_data.items() if v is not None}
    validation_result = swagger_validator.validate_json(request_data, "Pet")
    assert validation_result["valid"], f"Request schema validation failed: {validation_result}"

    # Make API request
    response = api_client.post(ENDPOINT.format(petId=pet_id), params=params)

    # Assert response status code
    assert response.status_code == expected_status_code, f"Unexpected status code: {response.status_code}"

    # Validate response schema
    response_validation = swagger_validator.validate_schema_by_response(
        endpoint=ENDPOINT,
        method='POST',
        status_code=str(expected_status_code),
        response=response
    )
    assert response_validation["valid"], f"Response schema validation failed: {response_validation}"

